'use strict';
const $ = (q, root=document) => root.querySelector(q);
const $$ = (q, root=document) => [...root.querySelectorAll(q)];
const esc = value => String(value ?? '').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone = value => JSON.parse(JSON.stringify(value));
const LABELS = {overview:'מבט על',schedule:'לוח הזמנים',questions:'שאלות לתרגול',flashcards:'כרטיסיות חזרה',readiness:'מצב הלימוד שלי',library:'חומרי הקורס'};
const ICONS = {overview:'◈',schedule:'▦',questions:'▤',readiness:'◴',library:'▱',flashcards:'▧'};
const STATUS = {unseen:'טרם תועד ניסיון',read:'קראתי והבנתי',guided:'פתרתי בעזרה',independent:'פתרתי עצמאית',timed:'פתרתי עצמאית בזמן'};
const KINDS = {setup:'התארגנות',study:'בניית בסיס',practice:'תרגול',review:'חזרה ותחקור',mock:'סימולציה'};
const DAYS = {setup:'ערב התארגנות',workday:'יום עבודה',deep:'יום עומק',light:'חזרה קצרה',reserve:'עתודה',exam:'יום הבחינה'};
let curriculum, schedule, flashcards, state, page='overview', activeDate, selectedDate, questionFilters={topic:'all',priority:'all',status:'all',search:''}, saveQueue=Promise.resolve(), toastTimer, activeDialog=null;
const main = $('#main');
const dayDate = d => new Date(d+'T12:00:00+03:00');
const fmtDate = (d,opts={day:'numeric',month:'long'}) => dayDate(d).toLocaleDateString('he-IL',opts);
const fmtDay = d => fmtDate(d,{weekday:'long'});
const dateNow = () => new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Jerusalem',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const timeLabel = mins => mins < 60 ? `${mins} דק׳` : mins===60?'שעה':mins%60===0?`${mins/60} שעות`:`${Math.floor(mins/60)} ש׳ ו־${mins%60} דק׳`;
const arr = x => Array.isArray(x)?x:x?[x]:[];
const sourceOf = id => curriculum.sources[id];
const topicOf = id => curriculum.topics.find(t=>t.id===id);
const problemOf = id => curriculum.problems.find(p=>p.id===id);
const allSessions = () => [...schedule.sessions,...(state.settings.customSessions||[])].map(s=>({...s,...(state.sessionUpdates[s.id]||{})}));
const sessionOf = id => allSessions().find(s=>s.id===id);
const dayOf = date => ({...schedule.days.find(d=>d.date===date),...(state.dayOverrides[date]||{}),date});
const isDone = s => s.status==='completed';
const sessionsOn = date => allSessions().filter(s=>s.date===date&&!s.disabled).sort((a,b)=>(a.start||'23:59').localeCompare(b.start||'23:59'));
const problemStatus = id => state.problemProgress[id]?.status||'unseen';
const isIndependent = id => ['independent','timed'].includes(problemStatus(id));
const extraMinutes = d => Number(d.optionalMinutes||0)+Number(d.conditionalMinutes||0);
const isCommitted = s => !s.conditional||!!dayOf(s.date).confirmedOptional;
const safeDate = d => d<'2026-09-21'?'2026-09-21':d>'2026-10-08'?'2026-10-08':d;
const mockIsValid = s => isDone(s)&&s.mock?.uninterrupted&&s.mock?.noHelp&&s.mock?.newQuestions&&s.actualMinutes>0&&s.actualMinutes<=150;
function planningIssues(s,date=s.date,start=s.start){
 const issues=[],day=dayOf(date),committed=isCommitted({...s,date});
 const load=sessionsOn(date).filter(x=>x.id!==s.id&&isCommitted(x)).reduce((n,x)=>n+x.minutes,0)+(committed?s.minutes:0);
 if(load>capacity(date))issues.push(`חריגה של ${load-capacity(date)} דקות מהקיבולת`);
 const minute=t=>{const [h,m]=t.split(':').map(Number);return h*60+m;};
 if(start){const begin=minute(start),end=begin+s.minutes;const windows=arr(day.windows).filter(w=>!w.conditional||day.confirmedOptional||s.conditional);
 if(!windows.some(w=>begin>=minute(w.start)&&end<=minute(w.end)))issues.push('השעה אינה בתוך חלון לימוד ידוע');
 for(const other of sessionsOn(date).filter(x=>x.id!==s.id&&x.start&&isCommitted(x))){if(begin<minute(other.start)+other.minutes&&end>minute(other.start))issues.push(`חפיפה עם ״${other.title}״`);}
 }
 const before=(aDate,aStart,bDate,bStart)=>aDate<bDate||aDate===bDate&&(aStart||'00:00')<(bStart||'00:00');
 for(const id of arr(s.dependsOn)){const dep=sessionOf(id);if(dep&&!isDone(dep)&&!before(dep.date,dep.start,date,start))issues.push(`תנאי הקדם ״${dep.title}״ משובץ אחרי היחידה`);}
 for(const dependent of allSessions().filter(x=>!isDone(x)&&arr(x.dependsOn).includes(s.id))){if(!before(date,start,dependent.date,dependent.start))issues.push(`״${dependent.title}״ תלויה ביחידה הזאת אך משובצת לפניה`);}
 return issues;
}
const officialProblems = () => curriculum.problems.filter(p=>/^m\d+-q\d+$|^sample-q\d+$/.test(p.id)&&!p.optional);
const mainProblemCount = () => officialProblems().filter(p=>isIndependent(p.id)).length;
const sourceUrl = (source,pageNo) => StudyStorage.sourceUrl(source,Number(pageNo)||1);
const pageValue = value => typeof value==='object'&&value!==null?(value.pdf||value.from||value.page||1):value;
const sourceLink = (id,pages,label) => {const s=sourceOf(id);if(!s)return '';const n=pageValue(arr(pages)[0])||1;return `<a class="source-link" href="${esc(sourceUrl(s,n))}" target="_blank" rel="noopener">${esc(label||s.label)}<span>PDF · עמ׳ ${esc(arr(pages).map(pageValue).join(', ')||n)} ↗</span></a>`;};
const tag = (label,style='') => `<span class="tag ${style}">${esc(label)}</span>`;
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('toast');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('toast'),4200);}
function save(fn,message){
  saveQueue=saveQueue.catch(()=>{}).then(async()=>{
    $('#save-status').textContent='שומר שינויים…';
    const next=clone(state);fn(next);
    let data;try{data=await StudyStorage.save(next,state.revision);}catch(error){if(error.status===409)error.message='התוכנית עודכנה בחלון אחר. רענן את הדף לפני שמירה נוספת.';throw error;}
    state=data;$('#save-status').textContent=StudyStorage.mode==='static'?'✓ נשמר בדפדפן הזה':'✓ השינויים נשמרו במחשב';
    render();if(message)notify(message);
  }).catch(err=>{$('#save-status').textContent='השינוי לא נשמר';notify(err.message);throw err;});
  return saveQueue;
}
function currentPage(){const hash=location.hash.slice(1);return LABELS[hash]?hash:'overview';}
function render(){
  page=currentPage();document.title=`מצפן · ${LABELS[page]}`;$('#page-label').textContent=LABELS[page];
  $('#nav').innerHTML=Object.entries(LABELS).map(([key,label])=>`<a class="nav-link ${page===key?'active':''}" href="#${key}" ${page===key?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${ICONS[key]}</span><span class="nav-label">${label}</span>${key==='questions'?`<span class="nav-count">${curriculum.problems.length}</span>`:''}</a>`).join('');
  main.innerHTML=({overview:renderOverview,schedule:renderSchedule,questions:renderQuestions,readiness:renderReadiness,library:renderLibrary,flashcards:()=>StudyCards.render()})[page]();
  document.documentElement.dataset.theme=state.settings.theme||'dark';
  $('#theme-button').textContent=state.settings.theme==='light'?'☾ מעבר לתצוגה כהה':'☼ מעבר לתצוגה בהירה';
}
function heading(title,subtitle,tools=''){return `<div class="page-heading"><div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div>${tools?`<div class="heading-tools">${tools}</div>`:''}</div>`;}
function dependencyIssues(s){return arr(s.dependsOn).map(sessionOf).filter(Boolean).filter(x=>!isDone(x));}
function nextSession(){
 const pending=allSessions().filter(s=>!isDone(s)&&!s.disabled&&isCommitted(s)).sort((a,b)=>a.date.localeCompare(b.date)||(a.start||'').localeCompare(b.start||''));
 return pending.find(s=>s.date<=activeDate&&!dependencyIssues(s).length)||pending.find(s=>!dependencyIssues(s).length)||pending[0];
}
function totalPlanned(date,includeConditional=true){return sessionsOn(date).filter(s=>includeConditional||isCommitted(s)).reduce((n,s)=>n+s.minutes,0);}
function capacity(date){const d=dayOf(date);return Number(d.capacityMinutes||0)+(d.confirmedOptional?extraMinutes(d):0);}
function overDays(){return schedule.days.filter(d=>totalPlanned(d.date,false)>capacity(d.date));}
function sessionRow(s){return `<button class="session-row ${isDone(s)?'completed':''}" data-action="session" data-id="${esc(s.id)}"><span class="session-icon" aria-hidden="true">${isDone(s)?'✓':s.kind==='mock'?'◷':s.kind==='setup'?'⚑':'↗'}</span><span><h3>${esc(s.title)}</h3><span class="session-meta"><bdi>${esc(s.start||'גמיש')}</bdi><span>·</span><span>${timeLabel(s.minutes)}</span><span>·</span><span>${esc(KINDS[s.kind]||s.kind)}</span>${s.conditional?tag(isCommitted(s)?'החלון אושר':'תלוי בזמינות',isCommitted(s)?'green':'gold'):''}${isDone(s)?tag('בוצע','green'):''}</span></span><span class="arrow" aria-hidden="true">‹</span></button>`;}
function renderOverview(){
 const next=nextSession(),today=dayOf(activeDate),done=allSessions().filter(isDone), upcoming=schedule.days.filter(d=>d.date>=activeDate).slice(0,7), remaining=allSessions().filter(s=>!isDone(s)&&!s.disabled&&isCommitted(s)&&s.kind!=='setup').reduce((n,s)=>n+s.minutes,0);
 const overdue=allSessions().filter(s=>s.date<activeDate&&!isDone(s)&&!s.disabled&&isCommitted(s));const daysLeft=Math.max(0,Math.round((dayDate('2026-10-08')-dayDate(activeDate))/86400000));
 const todaySessions=sessionsOn(activeDate), workload=totalPlanned(activeDate,false),passed=activeDate>='2026-10-08';
 return heading('יש לך מפה. עכשיו גם מצפן.', 'תוכנית מדורגת מהבסיס לפתרון עצמאי. הצעד הבא, הזמן שנותר והראיות להתקדמות — במקום אחד.',`<label class="small-text muted" for="active-date">תאריך עבודה</label><input id="active-date" class="date-select" type="date" min="2026-09-21" max="2026-10-08" value="${activeDate}">`)+
 `<div class="grid-two section">${window.StudyRecommendations?.enabled()?StudyRecommendations.card():`<section class="panel hero"><div><div class="status-line"><span class="eyebrow">${next?.kind==='setup'?'להיום · בדיקת התוכנית':'המשימה הבאה'}</span>${next?tag(`${fmtDate(next.date)} · ${timeLabel(next.minutes)}`):''}</div><h2>${esc(next?.title||'כל המשימות המתוכננות הושלמו')}</h2><p>${esc(next?.objective||'כעת אפשר לבדוק אילו שאלות נפתרו עצמאית, ומה כדאי לחזק לקראת הבחינה.')}</p></div><div class="hero-bottom">${next?`<button class="button primary" data-action="session" data-id="${esc(next.id)}">${next.kind==='setup'?'בדיקת ימי הלימוד':'פתיחת המשימה'} <span aria-hidden="true">←</span></button>`:''}<a href="#schedule" class="button">למפת הדרך</a></div></section>`}<section class="panel readiness-brief"><span class="eyebrow">הערכת מצב</span><h3>${curriculum.meta.diagnosticCompleted?'מה למדנו מהאבחון?':'נקודת הפתיחה שלך'}</h3><p>${esc(curriculum.meta.assessment)}</p><p class="hint">אין עדיין בסיס להערכת ציון או קצב פתרון בבחינה.</p><a class="text-link" href="#readiness">למצב הלימוד שלי <span>←</span></a></section></div>`+
 `<div class="metrics"><div class="metric"><span class="metric-label">עד הבחינה</span><strong class="number">${daysLeft}<small>ימים</small></strong><p>8.10 · 150 דקות · חומר סגור</p></div><div class="metric"><span class="metric-label">משימות שסיימת</span><strong class="number"><bdi>${done.length} <small>/ ${allSessions().filter(s=>!s.disabled).length}</small></bdi></strong><p>מצב הפתרון בשאלות נרשם בנפרד</p></div><div class="metric"><span class="metric-label">שאלות חובה שנפתרו עצמאית</span><strong class="number"><bdi>${mainProblemCount()} <small>/ ${officialProblems().length}</small></bdi></strong><p>14 שאלות ממ״ן + 3 דוגמאות המרצה</p></div><div class="metric"><span class="metric-label">זמן מתוכנן שנותר</span><strong class="number">${Number((remaining/60).toFixed(1))}<small>שעות</small></strong><p>כולל זמן לחזרה; ללא חלונות שלא אושרו</p></div></div>`+
 `${overdue.length?`<div class="notice">${overdue.length} משימות מתאריכים קודמים עדיין פתוחות. הן נשארות בתור; אפשר להזיז אותן ביומן ולבדוק את העומס לפני שמירה.</div>`:''}${overDays().length?`<div class="notice danger">יש עומס מעבר לזמן שהוקצה ב־${overDays().length} ימים. <a class="text-link" href="#schedule">בדיקת היומן ←</a></div>`:''}`+
 `<section class="section"><div class="section-head"><h2>השבוע הקרוב</h2><a class="text-link" href="#schedule">כל הדרך עד הבחינה ←</a></div><div class="week-strip">${upcoming.map(d=>`<button class="day-tile ${d.date===activeDate?'selected':''}" data-action="day" data-date="${d.date}"><span class="day-name">${fmtDay(d.date)}</span><span class="day-number">${fmtDate(d.date,{day:'numeric',month:'numeric'})}</span><span class="day-kind">${esc(DAYS[d.kind]||d.label||'לימוד')}</span><span class="day-hours">${totalPlanned(d.date,false)?timeLabel(totalPlanned(d.date,false)):d.reserveMinutes?'עתודה פנויה':'פנוי בתוכנית'}${totalPlanned(d.date)>totalPlanned(d.date,false)?' + מותנה':''}</span>${d.kind==='deep'?'<span class="day-dot"></span>':extraMinutes(d)?'<span class="day-dot gold"></span>':''}</button>`).join('')}</div></section>`+
 `${StudyCards.homeCard()}<div class="overview-bottom"><section><div class="section-head"><h2>${activeDate===dateNow()?'היום':fmtDate(activeDate)} · ${esc(DAYS[today.kind]||'התוכנית שלך')}</h2><span class="small-text muted">${timeLabel(workload)} מתוך ${timeLabel(capacity(activeDate))}</span></div><div class="agenda-list">${todaySessions.map(sessionRow).join('')||'<div class="list-empty">החלון נשמר לעתודה. אין צורך למלא אותו מראש.</div>'}</div>${activeDate==='2026-09-21'?'<div class="notice neutral">נקודת הפתיחה היא 21.9 בשעה 19:40. הערב מוקצה לבדיקת ימי הלימוד; שעות שכבר חלפו אינן חלק מהקיבולת.</div>':''}${!passed?'<div class="notice neutral">לא הספקת? פותחים את היחידה ומעבירים ליום מתאים. שום משימה לא נעלמת, והאתר מציג את השפעת ההעברה על העומס.</div>':''}</section><section class="panel"><div class="section-head"><h2>סדר העדיפויות שלנו</h2><span class="tag gold">מבוסס מקורות</span></div><div class="priority-list"><div class="priority-item"><span class="priority-number">01</span><div><strong>מה שנלמד בכיתה</strong><p>כולל ספי גרפים משיעור 3. שיעור 6 הוחרג לפי הבהרתך.</p></div></div><div class="priority-item"><span class="priority-number">02</span><div><strong>שאלות הממ״נים</strong><p>מועמדות לפי התאמה לכיתה ולתבניות הבחינה, ללא אחוזי הופעה מומצאים.</p></div></div><div class="priority-item"><span class="priority-number">03</span><div><strong>כל שלוש דוגמאות המרצה</strong><p>זנבות, דה־רנדומיזציה ומרקוב. הפתרונות המצורפים אינם שאלות נוספות.</p></div></div><div class="priority-item"><span class="priority-number">04</span><div><strong>ספר ומדריך לפי צורך</strong><p>קריאה ממוקדת שמשרתת פער או שאלה, בתוך הזמן המוגבל.</p></div></div></div></section></div>`;
}
function renderSchedule(){
 const selected=dayOf(selectedDate),start=dayDate(schedule.days[0].date).getDay(),cells=Array(start).fill('<div class="calendar-cell empty" aria-hidden="true"></div>');
 schedule.days.forEach(raw=>{const d=dayOf(raw.date),load=totalPlanned(d.date,false),cap=capacity(d.date),conditional=sessionsOn(d.date).filter(s=>!isCommitted(s)).reduce((n,s)=>n+s.minutes,0);cells.push(`<button class="calendar-cell ${d.date===selectedDate?'selected':''} ${d.kind==='exam'?'exam':''}" data-action="select-day" data-date="${d.date}" aria-label="${fmtDate(d.date)}: ${esc(DAYS[d.kind]||d.label)}; ${load} דקות מתוכננות מתוך ${cap}"><span class="date-num">${fmtDate(d.date,{day:'numeric',month:'numeric'})}</span><span class="cal-kind">${esc(DAYS[d.kind]||d.label||'')}</span><span class="load ${load>cap?'over':''}"><bdi>${load} / ${cap}</bdi> דק׳${conditional?' + מותנה':''}</span><span class="load-bar ${load>cap?'over':''}"><span style="width:${cap?Math.min(100,load/cap*100):load?100:0}%"></span></span></button>`);});
 const events=(schedule.calendarEvents||[]).filter(e=>(e.start||'').startsWith(selectedDate)&&!e.historical);
 return heading('מפת הדרך לבחינה','הימים העמוקים נושאים את עיקר ההתקדמות. ימי העבודה נועדו לחזרות קצרות, והעתודה נשארת פנויה לתיקון פערים.',`<button class="button primary small" data-action="custom-task">+ שיבוץ תיקון ממוקד</button><button class="button small" data-action="fallback">חלופה לסימולציה ב־28.9</button>`)+
 `<div class="calendar-layout"><section><div class="section-head"><h2>21 בספטמבר — 8 באוקטובר</h2><span class="tag">שעון ישראל</span></div><div class="calendar-grid">${['א׳','ב׳','ג׳','ד׳','ה׳','ו׳','ש׳'].map(d=>`<div class="calendar-heading">${d}</div>`).join('')}${cells.join('')}</div><div class="summary-pills">${tag('יום עומק ≈ 5 שעות מיקוד','green')}${tag('בוקר עבודה ≈ 45–60 דק׳')}${tag('חלונות עבודה נוספים אינם מובטחים','gold')}</div><div class="notice neutral">הפסים משווים זמן מתוכנן לקיבולת הממוקדת. הפסקות וזמן היומן הגולמי אינם נספרים כזמן לימוד. שינוי כאן מעדכן את התוכנית המקומית בלבד.</div><div class="milestones">${(schedule.milestones||[]).map(m=>`<div class="milestone"><span class="eyebrow">${esc(m.date?fmtDate(m.date):m.targetDate?fmtDate(m.targetDate):'תחנת בדיקה')}</span><strong style="display:block;margin-top:5px">${esc(m.title||m.label)}</strong><p>${esc(m.description||m.criterion||m.goal||'')}</p><details class="hint"><summary>אם עדיין לא הושג</summary>${esc(m.ifNotMet||'')}</details></div>`).join('')}</div></section><section class="panel day-detail"><div class="row-between"><span class="eyebrow">${fmtDay(selectedDate)}</span><button class="text-link" data-action="availability" data-date="${selectedDate}">עריכת זמינות</button></div><h2>${fmtDate(selectedDate)}</h2><p class="capacity-summary">${totalPlanned(selectedDate,false)} דקות מתוכננות · ${capacity(selectedDate)} דקות זמינות</p>${events.length?`<div class="windows">${events.map(e=>`<span class="tag">${esc(e.title)} <bdi>${String(e.start).slice(11,16)}–${String(e.end).slice(11,16)}</bdi></span>`).join('')}</div>`:''}<div class="agenda-list">${sessionsOn(selectedDate).map(sessionRow).join('')||'<div class="list-empty">אין משימות קבועות. אפשר להעביר לכאן משימה פתוחה דרך פרטי היחידה.</div>'}</div>${sessionsOn(selectedDate).filter(isCommitted).flatMap(s=>planningIssues(s)).length?`<div class="notice danger">${[...new Set(sessionsOn(selectedDate).filter(isCommitted).flatMap(s=>planningIssues(s)))].map(esc).join('<br>')}</div>`:''}${arr(selected.notes).length?`<p class="hint" style="margin-top:17px">${arr(selected.notes).map(esc).join('<br>')}</p>`:''}${extraMinutes(selected)?`<div class="notice">${extraMinutes(selected)} דקות נוספות תלויות בזמינות. ${selected.confirmedOptional?'סימנת שהחלון התפנה.':'הן לא נכללות בקיבולת הבטוחה.'}</div>`:''}${totalPlanned(selectedDate,false)>capacity(selectedDate)?'<div class="notice danger">היום חורג מהקיבולת. העבר יחידה ליום עם מקום לפני שמסתמכים על התוכנית.</div>':''}</section></div>`;
}
function questionTrackingStatus(id){const a=window.StudyMeetings?.latestProblemAttempt(id);return a&&['partial','stuck'].includes(a.outcome)?a.outcome:a&&problemStatus(id)==='unseen'?'attempted':problemStatus(id);}
function filteredProblems(){return curriculum.problems.filter(p=>{
 const f=questionFilters;return (f.topic==='all'||p.topicId===f.topic)&&(f.priority==='all'||f.priority==='mandatory'&&officialProblems().includes(p)||p.priority===f.priority)&&(f.status==='all'||f.status==='open'&&!isIndependent(p.id)||questionTrackingStatus(p.id)===f.status)&&(!f.search||[p.title,p.rationale,sourceOf(p.sourceId)?.label,topicOf(p.topicId)?.title].join(' ').toLowerCase().includes(f.search.toLowerCase()));
 }).sort((a,b)=>({high:0,core:1,support:2}[a.priority]-{high:0,core:1,support:2}[b.priority])||(a.candidateOrder||99)-(b.candidateOrder||99));}
function problemCard(p){const status=problemStatus(p.id);return `<article class="problem-card"><div><div class="status-line">${tag(sourceOf(p.sourceId)?.label||p.id)}${tag(topicOf(p.topicId)?.title||p.topicId)}${tag(p.priority==='high'?'מועמדת מובילה':p.priority==='core'?'ליבת ההכנה':p.candidateTier==='foundation'?'שאלת תשתית':'כיסוי משלים',p.priority==='high'?'gold':'')}</div><h3>${esc(p.title)}</h3><p>${esc(p.rationale||p.provenance||'')}</p></div><div class="problem-actions"><span class="problem-state ${status}">${esc(window.StudyMeetings?.problemLabel(p.id,STATUS[status]||STATUS.unseen)||STATUS[status]||STATUS.unseen)}</span><button class="button small" data-action="problem" data-id="${esc(p.id)}">פרטי השאלה והמעקב ←</button></div></article>`;}
function questionResults(){const results=filteredProblems();return `<div class="section-head"><span class="small-text muted">${results.length} שאלות ותבניות</span><span class="small-text muted">קריאה ← עזרה ← עצמאות ← זמן</span></div><div class="problem-list">${results.map(problemCard).join('')||'<div class="list-empty">אין שאלות שמתאימות לסינון. אפשר לבחור נושא או מצב אחר.</div>'}</div>`;}
function renderQuestions(){return heading('מפת השאלות','שש מועמדות ממ״ן מובילות, שאלות משלימות ותבניות הכיתה. הדירוג איכותני; סדר הלימוד ביומן מתחיל בתשתיות שהן דורשות.')+(window.StudyReviews?.panel()||'')+(window.StudyMixed?.panel()||'')+
 `<div class="notice neutral">לפי המידע שמסרת, שאלה מממ״ן צפויה בוודאות. אין בידינו מאגר מבחני עבר שמאפשר לזהות איזו. לכן ההכנה מכסה משפחות שאלות ומקדמת פתרון עצמאי, ולא שינון של ניחוש יחיד.</div><div class="filters"><input class="field-input search" id="problem-search" aria-label="חיפוש שאלה או נושא" placeholder="חיפוש שאלה, נושא או ממ״ן…" value="${esc(questionFilters.search)}"><select class="field-input" id="filter-topic" aria-label="סינון לפי נושא"><option value="all">כל הנושאים</option>${curriculum.topics.map(t=>`<option value="${t.id}" ${questionFilters.topic===t.id?'selected':''}>${esc(t.title)}</option>`).join('')}</select><select class="field-input" id="filter-priority" aria-label="סינון לפי עדיפות">${[['all','כל המקורות'],['mandatory','14 ממ״נים + 3 דוגמאות'],['high','מועמדות בעדיפות גבוהה'],['core','ליבת ההכנה'],['support','כיסוי משלים']].map(([v,l])=>`<option value="${v}" ${questionFilters.priority===v?'selected':''}>${l}</option>`).join('')}</select><select class="field-input" id="filter-status" aria-label="סינון לפי התקדמות">${[['all','כל המצבים'],['open','טרם נפתר עצמאית'],...(window.StudyMeetings?.enabled()?[['partial','ניסיון חלקי'],['stuck','ניסיתי ונתקעתי'],['attempted','ניסיון ללא סיכום עצמאות']]:[]),...Object.entries(STATUS)].map(([v,l])=>`<option value="${v}" ${questionFilters.status===v?'selected':''}>${l}</option>`).join('')}</select></div><div id="question-results">${questionResults()}</div>`;}
function renderReadiness(){
 const independent=officialProblems().filter(p=>isIndependent(p.id)),seen=officialProblems().filter(p=>problemStatus(p.id)!=='unseen'||window.StudyMeetings?.latestProblemAttempt(p.id)),mocks=allSessions().filter(s=>s.kind==='mock'&&mockIsValid(s)),logs=state.journal||[];
 return heading('מצב הלימוד שלי','כאן רואים את ממצאי האבחון ואת השאלות שכבר הצלחת לפתור. כך אפשר לבחור במה להתמקד בחזרות הבאות.')+
 `<div class="panel section"><span class="eyebrow">${curriculum.meta.diagnosticCompleted?'האבחון שכבר ביצעת':'נתוני הפתיחה'}</span><h2 style="margin:10px 0">${curriculum.meta.diagnosticCompleted?'מה כבר הודגם ומה דורש עבודה':'אפשר לייבא את נתוני ההכנה מהמחשב'}</h2><p class="muted">${esc(curriculum.meta.assessment)}</p>${curriculum.meta.diagnosticCompleted?`<div class="notice neutral">${esc(curriculum.meta.diagnosticLimit)} טעות יכולה לנבוע גם מחומר שנשכח או מסימון שלא הוסבר.</div>`:StudyStorage.mode==='static'?'<button class="button small" data-action="settings" style="margin-top:15px">יבוא ההתקדמות שלי</button>':''}</div>`+
 `<div class="metrics"><div class="metric"><span class="metric-label">שאלות שנגעת בהן מאז האבחון</span><strong>${seen.length}<small>/ 17</small></strong><p>כולל קריאה ותרגול בעזרה</p></div><div class="metric"><span class="metric-label">שאלות שסימנת כפתורות עצמאית</span><strong>${independent.length}<small>/ 17</small></strong><p>סימון שלך, עם תיעוד התוצאה</p></div><div class="metric"><span class="metric-label">סימולציות רצופות מתועדות</span><strong>${mocks.length}<small>/ 2</small></strong><p>ללא עזרה, עם שאלות חדשות ותיעוד זמן</p></div><div class="metric"><span class="metric-label">אבחון פתיחה</span><strong>${curriculum.meta.diagnosticCompleted?'בוצע':'לא יובא'}</strong><p>${curriculum.meta.diagnosticCompleted?'אין צורך לבצע שוב':'אפשר לייבא גיבוי מהמחשב'}</p></div></div>`+
 `<div class="topic-grid section">${curriculum.topics.map(t=>{const problems=curriculum.problems.filter(p=>p.topicId===t.id&&!p.optional),mastered=problems.filter(p=>isIndependent(p.id)).length;return `<article class="panel topic-card"><span class="eyebrow">${t.status==='foundation'?'בונים בסיס':'מפת היכולת'}</span><h3>${esc(t.title)}</h3><p class="readiness-text">${esc(t.readiness)}</p>${arr(t.strengths).length?`<span class="evidence-label">מה כבר הודגם</span><ul class="evidence-list">${arr(t.strengths).map(s=>`<li>${esc(s)}</li>`).join('')}</ul>`:''}<span class="evidence-label">מה עוד צריך ללמוד או לתרגל</span><ul class="evidence-list">${arr(t.gaps).map(s=>`<li>${esc(s)}</li>`).join('')}</ul><div class="coverage-footer"><span>${mastered} מתוך ${problems.length} תבניות תועדו כפתרון עצמאי</span><button class="text-link" data-action="topic-questions" data-id="${t.id}">לשאלות בנושא ←</button></div><div class="progress-track" role="progressbar" aria-label="פתרון עצמאי בנושא ${esc(t.title)}" aria-valuemin="0" aria-valuemax="${problems.length||1}" aria-valuenow="${mastered}"><div class="progress-fill" style="width:${problems.length?mastered/problems.length*100:0}%"></div></div></article>`;}).join('')}</div>`+
 `<section class="panel"><div class="section-head"><h2>יומן החלטות ולקחים</h2><button class="button small" data-action="journal">הוספת רשומה</button></div><p class="small-text muted">מה הפריע, מה עזר ומה משתנה בתוכנית. רשומה קצרה עדיפה על תחושת התקדמות עמומה.</p>${logs.length?logs.slice().reverse().slice(0,12).map(l=>`<div class="log-entry"><small>${esc((l.date||l.at||'').slice(0,10))} · ${esc(l.title||'רשומת הכנה')}</small><p>${esc(l.text||l.note||'')}</p></div>`).join(''):'<div class="list-empty" style="margin-top:16px">כאן יופיעו הרשומות שתוסיף ותחקורי היחידות שתשמור.</div>'}</section>`;
}
function renderLibrary(){
 const sources=Object.entries(curriculum.sources),groups=[['lectures','מחברות הכיתה',s=>s.kind==='lecture'||/Lectures\//.test(s.path)],['mamans','ממ״נים',s=>s.kind==='maman'||/Mamans\//.test(s.path)],['exam','הבחינה ודוגמאות המרצה',s=>/Test\//.test(s.path)],['reading','מדריך וספר — קריאה ממוקדת',s=>/Course (Guide|Book)/.test(s.path)]];
 const seen=new Set();
 return heading('המקורות במקום אחד','הקישורים פותחים את הקבצים המקוריים במחשב. בכל יחידה מופיעים גם העמודים והשאלות שמשרתים אותה.')+
 `<div class="panel section"><div class="row-between"><div><span class="eyebrow">חומר מותאם ליחידה</span><h2 style="margin-top:6px">מכינים את מפגש הלימוד הבא מתוך התוכנית</h2></div><button class="button" data-action="brief" data-id="${esc(nextSession()?.id||'')}">הצגת בקשה מוכנה למורה AI ←</button></div><p class="subtitle">בחר משימה וקבל טקסט שאפשר להדביק בשיחה עם המורה. הטקסט מציין מה ללמוד, מאילו קבצים ובאיזה סדר. ההוראה עצמה מתרחשת בשיחה, ולא באתר.</p></div>`+
 (StudyStorage.mode==='static'?`<section class="panel section"><h2>חיבור חומרי הקורס בדפדפן הזה</h2><p class="subtitle">קובצי הספר, ההרצאות והממ״נים נשארים אצלך. בחר פעם אחת את תיקיית הקורס כדי לפתוח כאן את ה־PDF הרלוונטי. הקבצים אינם נשלחים ל־GitHub.</p><button class="button" data-action="source-manager" style="margin-top:15px">חיבור תיקיית חומרי הקורס</button></section>`:'')+
 groups.map(([id,label,test])=>{const items=sources.filter(([key,s])=>!seen.has(key)&&test(s));items.forEach(([key])=>seen.add(key));return items.length?`<section class="library-group"><h2>${label}</h2><div class="library-grid">${items.map(([key,s])=>`<a class="source-card" href="${esc(sourceUrl(s,1))}" target="_blank" rel="noopener"><span class="source-icon">PDF</span><div><h3>${esc(s.label)}</h3><p>${esc(s.note||s.description||'פתיחה במקור המקומי')}</p></div><span class="out" aria-hidden="true">↗</span></a>`).join('')}</div></section>`:'';}).join('')+
 `<div class="notice neutral">שיעור 6 הוגדר כהעשרה לפי הבהרתך ולכן אינו חלק מתוכנית הליבה. הקבצים המקוריים והיומן שלך לא משתנים מתוך האתר.</div>`;
}
function openDialog(type,id,title,body,eyebrow='פרטי ההכנה'){
 activeDialog={type,id};$('#detail-dialog').classList.toggle('task-dialog',type==='session');$('#dialog-content').innerHTML=`<div class="dialog-header"><div><span class="eyebrow">${esc(eyebrow)}</span><h2 id="dialog-title" tabindex="-1">${esc(title)}</h2></div><button class="icon-button" data-action="close" aria-label="סגירה">×</button></div><div class="dialog-body">${body}</div>`;
 const dialog=$('#detail-dialog'),content=$('.dialog-body',dialog);
 if(window.StudyDialogScroll)StudyDialogScroll.open(dialog);else if(!dialog.open)dialog.showModal();
 $('#dialog-title').focus({preventScroll:true});dialog.scrollTop=0;content.scrollTop=0;
 requestAnimationFrame(()=>{if(content.isConnected){dialog.scrollTop=0;content.scrollTop=0;}});
}
function sessionSourceRefs(s){
 const refs=arr(s.problemIds).map(problemOf).filter(Boolean).map(p=>({sourceId:p.sourceId,pages:p.pages,label:p.title}));
 for(const r of arr(topicOf(s.topicId)?.reading))refs.push(r);
 for(const id of arr(s.sourceIds))refs.push({sourceId:id});
 if(s.kind==='mock'||s.id==='mock1-prepare'||s.id==='coverage-audit')refs.push({sourceId:'exam-notes',pages:[1,2,3]},{sourceId:'formula-sheet',pages:[3,4,5]});
 const unique=new Map();for(const r of refs){if(sourceOf(r.sourceId))unique.set(r.sourceId+JSON.stringify(r.pages||[]),r);}return [...unique.values()];
}
function sessionSources(s){return sessionSourceRefs(s).map(r=>sourceLink(r.sourceId,r.pages,r.label?`${sourceOf(r.sourceId).label} · ${r.label}`:null)).join('');}
function showSession(id){StudyTasks.open(id);}
function showProblem(id){const p=problemOf(id);if(!p)return;const progress=state.problemProgress[id]||{},associated=allSessions().filter(s=>arr(s.problemIds).includes(id));
 openDialog('problem',id,p.title,`<div class="status-line">${tag(topicOf(p.topicId)?.title||p.topicId)}${tag(p.priority==='high'?'מועמדת בעדיפות גבוהה':'חלק ממפת הכיסוי',p.priority==='high'?'gold':'')}</div><h3>למה היא בתוכנית</h3><p>${esc(p.rationale)}</p><p class="source-note">בסיס ההערכה: ${esc(p.provenance)}</p><h3>השאלה המקורית</h3><div class="source-links">${sourceLink(p.sourceId,p.pages)}</div><p class="hint">הנוסח המחייב נמצא ב־PDF המקורי. לא הוחלף כאן בניסוח מקוצר.</p><h3>מה היכולת שנרצה להדגים</h3><ul class="step-list">${arr(p.expectedSkills).map(s=>`<li>${esc(s)}</li>`).join('')}</ul><div class="notice neutral">${arr(p.completionCriteria).map(esc).join('<br>')}</div>${associated.length?`<p class="small-text muted">מתוכננת ב־${associated.map(s=>fmtDate(s.date)).join(', ')}.</p>`:'<div class="notice">אין כרגע יחידה המשויכת לשאלה. היא נשארת גלויה במפת הכיסוי.</div>'}<div class="divider"></div><form id="problem-form" data-id="${esc(id)}"><div class="form-grid"><div class="form-field"><label for="progress-status">מה הצלחת לעשות</label><select class="field-input" name="status" id="progress-status">${Object.entries(STATUS).map(([value,label])=>`<option value="${value}" ${(progress.status||'unseen')===value?'selected':''}>${label}</option>`).join('')}</select></div><div class="form-field"><label for="problem-minutes">זמן פתרון, בדקות (אם נמדד)</label><input class="field-input" type="number" name="minutes" id="problem-minutes" min="1" max="300" value="${esc(progress.minutes||'')}" placeholder="לא נמדד"></div><div class="form-field"><label for="problem-obstacle">מה היה החסם העיקרי</label><select class="field-input" id="problem-obstacle" name="obstacle">${[['','טרם זוהה / אין חסם'],['knowledge','חומר שעדיין לא למדתי'],['memory','שכחה או קושי בשליפה'],['notation','סימון או ניסוח לא ברור'],['model','בניית המודל או בחירת שיטה'],['calculation','טעות חישוב'],['time','קצב פתרון']].map(([v,l])=>`<option value="${v}" ${progress.obstacle===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="form-field"><label for="problem-date">תאריך התרגול</label><input class="field-input" type="date" name="date" id="problem-date" value="${esc(progress.date||activeDate)}" required></div><div class="form-field full"><label for="problem-evidence">תיעוד הביצוע — מה הצליח, כיצד נבדק, ואיזו עזרה נדרשה</label><textarea class="field-input" name="evidence" id="problem-evidence" placeholder="למשל: פתרתי בלי לפתוח את הפתרון, בדקתי מול פתרון המרצה; נותר פער בנימוק אי־התלות.">${esc(progress.evidence||'')}</textarea></div></div><label class="check-line"><input type="checkbox" name="independentConfirmed" ${progress.independentConfirmed?'checked':''}>אם סימנתי פתרון עצמאי: פתרתי בלי פתרון פתוח ובלי הכוונה, ובדקתי את הנימוק והתוצאה.</label><p class="hint">רישום עצמאי דורש תיעוד ואישור. האתר אינו בודק את הפתרון ומסתמך על הדיווח שלך.</p><p id="problem-error" class="error" role="alert"></p><div class="dialog-actions"><button type="submit" class="button primary">שמירת התקדמות</button><button type="button" class="button" data-action="problem-prompt" data-id="${esc(id)}">הכנת בקשה לתרגול עתידי</button></div></form>`,'שאלה · מקור · ראיות לביצוע');
 if(window.StudyMeetings?.enabled())StudyMeetings.decorateProblem(id);
}
function showAvailability(date){const d=dayOf(date);openDialog('availability',date,`זמינות · ${fmtDate(date)}`,`<p>הקיבולת היא זמן לימוד ממוקד שאפשר להסתמך עליו, אחרי הפסקות ועומס העבודה. שינוי הזמינות לא מזיז משימות אוטומטית.</p><form id="availability-form" data-date="${date}"><div class="form-grid" style="margin-top:18px"><div class="form-field"><label for="capacity-minutes">דקות לימוד ממוקדות זמינות</label><input class="field-input" type="number" min="0" max="600" step="5" id="capacity-minutes" name="capacityMinutes" value="${Number(d.capacityMinutes||0)}" required></div><div class="form-field"><label for="availability-note">הערת זמינות</label><input class="field-input" id="availability-note" name="notes" value="${esc(arr(d.notes).join(' '))}" placeholder="למשל: פנוי רק בשעות הבוקר"></div></div>${extraMinutes(d)?`<label class="check-line"><input type="checkbox" name="confirmedOptional" ${d.confirmedOptional?'checked':''}>החלון הנוסף של ${extraMinutes(d)} דקות התפנה בפועל ואפשר לכלול אותו בקיבולת.</label>`:''}<div class="notice neutral">כרגע משובצות ${totalPlanned(date,false)} דקות, ועוד ${totalPlanned(date)-totalPlanned(date,false)} דקות מותנות. חריגה תסומן ביומן.</div><button type="submit" class="button primary">שמירת זמינות</button></form>`,'התוכנית מסתגלת למציאות');}
function promptForSession(s){const base=window.StudyScaffold?.prompt(s.id)||basePromptForSession(s);const context=window.StudyMeetings?.enabled()?StudyLearningEngine.promptContext(state,s.id):'';const report=window.StudyReports?.prompt(s.id)||'';return [context,base,report].filter(Boolean).join('\n\n');}
function basePromptForSession(s){const t=topicOf(s.topicId),sources=sessionSourcesText(s);
 if(s.kind==='setup')return `עזור לי לסקור ולדייק את תוכנית ההכנה לבחינת אלגוריתמים אקראיים ב־8.10.2026. זהו שלב תכנון בלבד. אל תתחיל הוראה או אבחון נוסף.\nקרא את study-plan/STUDY_STATE.md ואת קובצי curriculum.json ו־schedule.json בתיקייה study-plan/dashboard/data. אם קיים progress.json, קרא אותו כדי להתחשב בהתקדמות ובעדכוני היומן.\nנקודת הפתיחה היא 21.9.2026 בשעה 19:40. האבחון כבר הושלם. בדוק את סדר היחידות, הקיבולת, תנאי הקדם והחלונות המותנים, ועזור לי לבחור את חלון הלימוד הבא בלי להתחיל אותו.\nהצג בעברית ברורה החלטות קונקרטיות והשלכות על הזמן; אל תנבא ציון ואל תניח שכל משימה שבוצעה מוכיחה שליטה.`;
 if(['mock1-review','mock2-review'].includes(s.id))return `עזור לי לבדוק ולתחקר את הסימולציה שביצעתי. בקש ממני את השאלות, הפתרונות שכתבתי, הזמן והעזרה שבה נעזרתי. אל תכין מבחן נוסף.\nבדוק כל סעיף לפי נוסח השאלה ומקורות הקורס. הפרד בין חוסר ידע או זיכרון, קושי בהבנת הסימון, בחירת שיטה וטעות חישוב. הסבר את הרקע החסר בעברית בהירה לפני התיקון הנקודתי.\nסיים בציון מבוסס מחוון לכל שאלה, שתי טעויות שכדאי לתקן תחילה והמלצה למשימת תיקון שנכנסת ב־${s.minutes} הדקות שהוקצו. אל תסיק ציון עתידי בבחינה.\nמקורות:\n${sources}`;
 if(s.kind==='mock'||s.id==='mock1-prepare'||s.id==='coverage-audit')return `הכן סט חדש של שלוש שאלות לסימולציה באלגוריתמים אקראיים, במשך 150 דקות ובתנאי הבחינה. איני מתחיל את הסימולציה כעת.\nקרא תחילה את study-plan/dashboard/data/curriculum.json, את schedule.json ואת progress.json אם קיים. חומר הכיתה הוא העוגן הראשון, ואחריו הממ״נים ושלוש הדוגמאות. שיעור 6 הוחרג כהעשרה.\nמקורות להנחיות הבחינה:\n${sources}\nבחר שאלות שאינן שחזור מילולי של שאלות שכבר למדתי, ובדוק את הפתרונות לפני מסירתן. בסימולציית הביניים ציין בנפרד אילו נושאים עדיין לא כוסו לפי התוכנית וההתקדמות.\nהכן דף שאלון נפרד ללא רמזים או פתרונות, בעברית ברורה ובמצב כהה, עם כל סימון מוגדר ונוסחאות מוצגות משמאל לימין. הכן פתרונות ומחוון בדיקה במסמך נפרד שלא יוצג לפני ניסיון. שלוש שאלות חובה; שתי התשובות הטובות שוות 40% כל אחת והשלישית 20%. תעד זמן, עזרה והפרעות בנפרד מהציון. אל תמציא נושאים או הגבלות שאינם במקורות ואל תציג ציון ביצוע כתחזית לבחינה.`;
 return `אנחנו מכינים אותי לבחינת אלגוריתמים אקראיים ב־8.10.2026. אני בוחר כעת להתחיל את היחידה: ${s.title}.\n\nמטרת היחידה: ${s.objective}\nזמן מתוכנן: ${s.minutes} דקות.\nסדר עבודה:\n${arr(s.steps).map((x,i)=>`${i+1}. ${x}`).join('\n')}\nתנאי סיום: ${arr(s.doneWhen).join(' ')}\n\nמקורות מקומיים שיש לקרוא לפני ניסוח תוכן:\n${sources}\n\nמצבי בנושא: ${t?.readiness||'זו יחידת תכנון או חזרה; הסתמך על אבחון הפתיחה שבתיקיית study-plan.'}\nפערים ידועים: ${arr(t?.gaps).join('; ')}\n\nכל ההוראה בעברית ברורה, כמו מורה פרטי. הגדר סימון ומושגים לפני שימוש בהם. ייתכן שחסרים לי ידע או זיכרון; אל תניח שהטעות היא רק בחשיבה. נוסחאות בשורה נפרדת ומשמאל לימין; אם נוצר עמוד, מצב כהה כברירת מחדל. אל תחשוף פתרון לפני ניסיון שלי. התקדם מהדגמה מוסברת לתרגול מודרך ואז לפתרון עצמאי של וריאציה. שמור על הנוסח המחייב והגבלות השאלה במקור. שאל שאלה אחת ברורה בכל שלב. אל תסיק ציון צפוי מהאבחון. בסוף תן תיעוד קצר של מה הודגם ומה נותר, כדי שאעדכן את האתר.\n\nאם קובץ אינו זמין, ציין זאת ואל תמציא את תוכנו.`;}
function sessionSourcesText(s){return sessionSourceRefs(s).map(r=>{const src=sourceOf(r.sourceId);return `- ${src.label}: ${src.path}${r.pages?.length?' | עמודי PDF: '+r.pages.join(', '):''}${r.label?' | '+r.label:''}`;}).join('\n')||'- study-plan/תוכנית-הכנה.md\n- study-plan/STUDY_STATE.md';}
function mockFields(s){const m=s.mock||{},scores=arr(m.scores),complete=scores.length===3&&scores.every(x=>typeof x==='number'&&Number.isFinite(x)),sorted=complete?[...scores].sort((a,b)=>b-a):[],score=complete?Math.round((sorted[0]*.4+sorted[1]*.4+sorted[2]*.2)*10)/10:null;return `<div class="notice neutral">כדי לספור סימולציה כמדידת מוכנות צריך שאלות חדשות, זמן שנמדד ועד 150 דקות רצופות ללא עזרה. גם ניסיון שהופרע חשוב לתחקור, אך לא ייספר כמדידת זמן תקפה.</div><label class="check-line"><input type="checkbox" name="mockUninterrupted" ${m.uninterrupted?'checked':''}>הביצוע היה רצוף, ללא הפרעות עבודה או עצירות ללימוד.</label><label class="check-line"><input type="checkbox" name="mockNoHelp" ${m.noHelp?'checked':''}>לא נעזרתי ברמזים או בפתרונות; רק בדף הנוסחאות המותר.</label><label class="check-line"><input type="checkbox" name="mockNewQuestions" ${m.newQuestions?'checked':''}>אלו שאלות שלא פתרתי או למדתי את פתרונן מראש.</label><p class="small-text muted">אחרי בדיקה: אחוז הנקודות בכל שאלה, בין 0 ל־100. השאר ריק כל עוד התשובות לא נבדקו.</p><div class="form-grid" style="margin:14px 0">${[1,2,3].map(n=>`<div class="form-field"><label for="mock-score-${n}">שאלה ${n} · אחוז נקודות</label><input class="field-input" id="mock-score-${n}" name="score${n}" type="number" min="0" max="100" step="0.5" value="${scores[n-1]??''}"></div>`).join('')}</div>${score!==null?`<div class="notice">ציון הביצוע לפי דיווחך: ${score}. שתי התשובות הטובות במשקל 40% והשלישית 20%. זה אינו ציון חזוי לבחינה.</div>`:''}`;}
function showCustomTask(){const date=schedule.days.find(d=>d.date>=activeDate&&capacity(d.date)-totalPlanned(d.date,false)>=45)?.date||'2026-10-07';openDialog('custom-task','custom','שיבוץ תיקון ממוקד',`<p>משימה חדשה צריכה לענות על פער מסוים שזוהה בביצוע. מקצים לה זמן מפורש כדי שלא תהפוך לרשימת מטלות שאינה נכנסת ביומן.</p><form id="custom-task-form"><div class="form-grid" style="margin-top:18px"><div class="form-field full"><label for="custom-title">שם המשימה</label><input class="field-input" id="custom-title" name="title" placeholder="למשל: ניסיון עצמאי נוסף בשאלת זמן פגיעה" required maxlength="160"></div><div class="form-field"><label for="custom-topic">נושא</label><select class="field-input" id="custom-topic" name="topicId">${curriculum.topics.map(t=>`<option value="${t.id}">${esc(t.title)}</option>`).join('')}</select></div><div class="form-field"><label for="custom-problem">שאלה למעקב (אם רלוונטי)</label><select class="field-input" id="custom-problem" name="problemId"><option value="">ללא שיוך לשאלה</option>${curriculum.problems.map(p=>`<option value="${p.id}">${esc(p.title)}</option>`).join('')}</select></div><div class="form-field"><label for="custom-date">תאריך</label><input class="field-input" type="date" id="custom-date" name="date" value="${date}" min="2026-09-21" max="2026-10-08" required></div><div class="form-field"><label for="custom-time">שעת התחלה</label><input class="field-input" type="time" id="custom-time" name="start"></div><div class="form-field"><label for="custom-minutes">תקציב דקות</label><input class="field-input" type="number" id="custom-minutes" name="minutes" min="10" max="180" step="5" value="45" required></div><div class="form-field full"><label for="custom-objective">הפער והתוצר הרצוי</label><textarea class="field-input" id="custom-objective" name="objective" required placeholder="מה בדיוק צריך להשתפר, ואיך נדע שהצליח?"></textarea></div></div><div class="notice neutral" id="custom-impact">ביום המוצע נשארו ${Math.max(0,capacity(date)-totalPlanned(date,false))} דקות לפני הוספת התיקון.</div><div class="dialog-actions"><button class="button primary" type="submit">הוספת היחידה לתוכנית</button></div></form>`,'תיקון שנכנס בזמן');}
function showBrief(id){
 const s=sessionOf(id);if(!s)return;
 openDialog('brief',id,'בקשה מוכנה ל־AI',`<p>העתק את הבקשה והדבק בשיחה עם AI שיש לו גישה לקובצי הקורס. היא כוללת את מטרת המשימה, המקורות ואופן ההסבר שמתאים לך.</p><label class="prompt-label" for="prompt-text">הבקשה להעתקה</label><textarea class="prompt-preview prompt-textarea" id="prompt-text" readonly rows="12" spellcheck="false">${esc(promptForSession(s))}</textarea><div class="prompt-manual"><button class="text-link" data-action="select-prompt">בחירת כל הטקסט</button><p class="hint">להעתקה ידנית בטלפון: בחר את הטקסט, לחץ עליו לחיצה ארוכה ובחר ״העתק״.</p></div>`,'להדבקה בשיחה');
 const footer=document.createElement('div');footer.className='task-fixed-actions prompt-fixed-actions';
 footer.innerHTML=`<button class="button primary task-copy-button" data-action="copy-prompt">העתקת הבקשה</button><button class="button" data-action="session" data-id="${id}">חזרה למשימה</button><button class="text-link" data-action="download-brief" data-id="${id}">הורדת הוראות המשימה</button>`;
 $('#dialog-content').append(footer);
}
function selectPromptText(){
 const field=$('#prompt-text');if(!field)return;
 if(field.tagName==='TEXTAREA'){field.focus({preventScroll:true});field.select();field.setSelectionRange(0,field.value.length);}
 else{const selection=window.getSelection(),range=document.createRange();range.selectNodeContents(field);selection.removeAllRanges();selection.addRange(range);}
}
function markPromptCopied(button){
 if(!button)return;
 button.dataset.copyLabel||=button.textContent;clearTimeout(button.copyFeedbackTimer);
 button.textContent='הבקשה הועתקה ✓';
 button.copyFeedbackTimer=setTimeout(()=>{if(button.isConnected)button.textContent=button.dataset.copyLabel;},3000);
}

function showProblemPrompt(id){const p=problemOf(id);const text=`אני רוצה לעבוד על ${p.title}, במסגרת ההכנה לבחינת אלגוריתמים אקראיים.\nמקור: ${sourceOf(p.sourceId)?.path}, עמודי PDF ${arr(p.pages).join(', ')}.\nקרא תחילה את המקור כדי לשמור את הנוסח וההגבלות.\nמצב מתועד: ${window.StudyMeetings?.problemLabel(id,STATUS[problemStatus(id)])||STATUS[problemStatus(id)]}.\n${window.StudyMeetings?.problemContext(id)||''}מה צריך להדגים: ${arr(p.expectedSkills).join('; ')}.\nתנאי סיום: ${arr(p.completionCriteria).join('; ')}.\n\nלמד בעברית ברורה ובהדרגה. הגדר כל סימון. בדוק אם חסר לי ידע או זיכרון לפני תיקון נקודתי. אל תציג פתרון מראש. תן מקום לניסיון עצמאי, ולאחר מכן וריאציה שבודקת העברה של השיטה. הפרד נוסחאות משמאל לימין והשתמש במצב כהה בדפים חדשים. אם המקור אינו זמין, אל תמציא אותו.`;openDialog('problem-prompt',id,'בקשה לתרגול עתידי',`<p>הבקשה מקשרת לשאלה וליכולת שנרצה לבסס. העתק אותה לשיחה כשתרצה להתחיל.</p><pre class="prompt-preview" id="prompt-text">${esc(text)}</pre><div class="dialog-actions"><button class="button primary" data-action="copy-prompt">העתקת הבקשה</button><button class="button" data-action="problem" data-id="${id}">חזרה לשאלה</button></div>`);}
function downloadFile(filename,text,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function downloadBrief(id){const s=sessionOf(id),html=`<!doctype html><html lang="he" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>${esc(s.title)}</title><style>body{background:#101813;color:#eaf0e9;font:17px/1.9 'Segoe UI',Arial;max-width:850px;margin:50px auto;padding:24px}h1,h2{color:#bce9a5}li{margin:12px 0}pre{white-space:pre-wrap;font:inherit;color:#b3c1b7;border:1px solid #344b39;padding:24px;border-radius:12px}small{color:#a2b09f}</style><h1>${esc(s.title)}</h1><small>${fmtDate(s.date)} · ${timeLabel(s.minutes)} · תוכנית הכנה לבחינה</small><h2>מטרה</h2><p>${esc(s.objective)}</p><h2>סדר עבודה</h2><ol>${arr(s.steps).map(x=>`<li>${esc(x)}</li>`).join('')}</ol><h2>תנאי סיום</h2><p>${arr(s.doneWhen).map(esc).join('<br>')}</p><h2>בקשה מוכנה להוראה</h2><pre>${esc(promptForSession(s))}</pre><small>תיק תכנון מקומי. אין כאן בדיקה אוטומטית או פתרון שנוצר על ידי מודל.</small></html>`;downloadFile(`study-unit-${id}.html`,html,'text/html;charset=utf-8');notify('הוראות המשימה הורדו');}
function showFallback(){const c=(schedule.contingencies||[]).find(x=>x.id==='mock-unavailable')||(schedule.contingencies||[])[0],moves=c?.moves||[];openDialog('fallback',c?.id,'אם חלון הסימולציה לא מתפנה',`<p>28.9 הוא חלון עבודה מהבית, ולכן 150 דקות רצופות אינן מובטחות. סימולציה עם הפרעות תירשם כתרגול, ולא כמדידה אמינה של ביצוע בזמן בחינה.</p><div class="notice neutral">${esc(c?.description||'אפשר להעביר את הסימולציה ל־29.9 ולפנות עבורה זמן מתוך יחידות היום. יתרת יחידות מרקוב וגרפים תעבור ל־1.10 ולעתודה של 7.10. ההעברה חייבת לשמור על קיבולת הימים.')}</div>${moves.length?`<h3>השינוי המוצע</h3><div class="plan-b">${moves.map(m=>{const s=sessionOf(m.sessionId);return s?`<div class="radio-row"><strong>${esc(s.title)}</strong><p>${fmtDate(s.date)} ← ${fmtDate(m.date)}${m.start?' · '+esc(m.start):''} · ${timeLabel(m.minutes||s.minutes)}</p></div>`:'';}).join('')}</div><div class="notice">החלת החלופה משנה רק יחידות שטרם בוצעו. אם ערכת כבר את הקיבולת או העברת משימות, יש לבדוק מחדש את העומס שמוצג ביומן.</div><div class="notice neutral">${arr(c.effects).map(esc).join('<br>')}</div><div class="dialog-actions"><button class="button primary" data-action="apply-fallback" data-id="${esc(c.id)}">החלת החלופה ובדיקת העומס</button></div>`:'<div class="dialog-actions"><a class="button" href="#schedule" data-action="close">פתיחת היומן להזזה ידנית</a></div>'}`,'תוכנית חלופית · בלי להוסיף שעות');}
function showSettings(){openDialog('settings','settings','הגדרות וגיבוי',`<p>${StudyStorage.mode==='static'?'ההתקדמות נשמרת בדפדפן ובמכשיר הזה. היא אינה נשלחת ל־GitHub. לפני מעבר מכשיר או ניקוי נתוני דפדפן, הורד גיבוי.':'התוכנית וההתקדמות נשמרות בקובץ מקומי. לפני כל שינוי נשמר גם עותק גיבוי.'}</p><div class="notice neutral">יצוא מוריד קובץ עם ההתקדמות שלך. יבוא טוען אותו במכשיר אחר או בגרסה המקוונת. אין סנכרון אוטומטי בין דפדפנים או עם היומן.</div><div class="dialog-actions"><button class="button primary" data-action="export">יצוא התקדמות וגיבוי</button><button class="button" data-action="import">יבוא גיבוי</button><button class="button" data-action="theme">${state.settings.theme==='light'?'מצב כהה':'מצב בהיר'}</button></div><input type="file" accept="application/json,.json" id="import-file" hidden><div class="divider"></div><h3>תאריך העבודה</h3><p class="small-text muted">המסך הראשי משתמש בתאריך העבודה שבחרת. אפשר לחזור לתאריך הנוכחי בשעון ישראל.</p><button class="button small" data-action="today" style="margin-top:12px">מעבר להיום</button><p class="hint">גרסת נתונים ${state.schemaVersion} · שמירה ${state.revision}. קובצי הקורס המקוריים נשארים במיקומם.</p>`,'המרחב האישי שלך');}
function showJournal(){openDialog('journal','journal','רשומה ליומן ההכנה',`<form id="journal-form"><div class="form-field"><label for="journal-title">כותרת קצרה</label><input class="field-input" id="journal-title" name="title" placeholder="למשל: מה השתנה בזמינות השבוע" required maxlength="140"></div><div class="form-field" style="margin-top:14px"><label for="journal-text">מה כדאי לזכור להמשך</label><textarea class="field-input" id="journal-text" name="text" required placeholder="החלטה, חסם או מסקנה שמשפיעים על התוכנית."></textarea></div><div class="dialog-actions"><button class="button primary" type="submit">שמירת רשומה</button></div></form>`);}
function closeDialog(options={}){const dialog=$('#detail-dialog');if(window.StudyDialogScroll)StudyDialogScroll.close(dialog,options);else dialog.close();activeDialog=null;}
function updateMoveImpact(){if(!['session','task-edit'].includes(activeDialog?.type))return;const s=sessionOf(activeDialog.id),date=$('#session-date').value;if(!date)return;const start=$('#session-time').value,issues=planningIssues(s,date,start),load=sessionsOn(date).filter(x=>x.id!==s.id&&isCommitted(x)).reduce((n,x)=>n+x.minutes,0)+(isCommitted({...s,date})?s.minutes:0),cap=capacity(date);$('#move-impact').textContent=`אחרי ההעברה: ${load} דקות מתוך ${cap} זמינות ב־${fmtDate(date)}. ${issues.join(' · ')}`;$('#move-impact').className=issues.length?'notice danger':'notice neutral';}
document.addEventListener('click',async event=>{
 const button=event.target.closest('[data-action]');if(!button)return;const {action,id,date}=button.dataset;
 try{
 if(action==='close'){closeDialog();return;}
 if(action==='settings')showSettings();
 if(action==='source-manager')SourceLibrary.openManager();
 if(action==='export')await exportProgress();
 if(action==='session')showSession(id);
 if(action==='problem')showProblem(id);
 if(action==='day'){selectedDate=date;location.hash='schedule';if(page==='schedule')render();}
 if(action==='select-day'){selectedDate=date;render();}
 if(action==='availability')showAvailability(date);
 if(action==='custom-task')showCustomTask();
 if(action==='topic-questions'){questionFilters.topic=id;location.hash='questions';}
 if(action==='brief')showBrief(id);
 if(action==='problem-prompt')showProblemPrompt(id);
 if(action==='download-brief')downloadBrief(id);
 if(action==='select-prompt')selectPromptText();
 if(action==='copy-prompt'){try{const field=$('#prompt-text');await navigator.clipboard.writeText(field.value??field.textContent);markPromptCopied(button);notify('הבקשה הועתקה. אפשר להדביק אותה בשיחה.');}catch{selectPromptText();notify('הטקסט נבחר. בטלפון: לחץ עליו לחיצה ארוכה ובחר ״העתק״.');}}
 if(action==='fallback')showFallback();
 if(action==='apply-fallback'){const mock=sessionOf('mock1');if(mock&&(mock.status==='in-progress'||isDone(mock)||Number(mock.actualMinutes)>0)){notify('כבר תועד ביצוע בסימולציה. יש לבחור סט חדש ולשבץ ידנית לפי התחקור.');return;}const c=(schedule.contingencies||[]).find(x=>x.id===id);if(!c?.moves?.length)return;await save(d=>{c.moves.forEach(m=>{if(!isDone(sessionOf(m.sessionId)||{}))d.sessionUpdates[m.sessionId]={...(d.sessionUpdates[m.sessionId]||{}),...Object.fromEntries(Object.entries(m).filter(([k])=>k!=='sessionId')),conditional:false};});arr(c.dayOverrides).forEach(o=>{const {date,...values}=o;d.dayOverrides[date]={...(d.dayOverrides[date]||{}),...values};});d.settings.fallbackApplied=id;d.journal.push({date:activeDate,title:'הופעלה חלופת הסימולציה',text:c.description||'חלון 28.9 לא התאפשר; היחידות הועברו לפי החלופה.'});},'החלופה הוחלה. העומס המעודכן מוצג ביומן.');closeDialog();selectedDate='2026-09-29';location.hash='schedule';render();}
 if(action==='journal')showJournal();
 if(action==='theme'){await save(d=>{d.settings.theme=d.settings.theme==='light'?'dark':'light';});showSettings();}
 if(action==='today'){activeDate=dateNow();activeDate=activeDate<'2026-09-21'?'2026-09-21':activeDate>'2026-10-08'?'2026-10-08':activeDate;selectedDate=activeDate;await save(d=>{d.settings.activeDate=activeDate;});closeDialog();}
 if(action==='import')$('#import-file').click();
 }catch(err){if(!$('#save-status').textContent.includes('לא נשמר'))notify(err.message);}
});
document.addEventListener('input',event=>{if(event.target.id==='problem-search'){questionFilters.search=event.target.value;$('#question-results').innerHTML=questionResults();}if(['session-date','session-time'].includes(event.target.id))updateMoveImpact();if(['custom-date','custom-time','custom-minutes'].includes(event.target.id)){const date=$('#custom-date').value,minutes=Number($('#custom-minutes').value),start=$('#custom-time').value;if(date&&minutes){const issues=planningIssues({id:'new-task',minutes,conditional:false,dependsOn:[]},date,start);$('#custom-impact').textContent=`לאחר השיבוץ: ${totalPlanned(date,false)+minutes} דקות מתוך ${capacity(date)} זמינות. ${issues.join(' · ')}`;$('#custom-impact').className=issues.length?'notice danger':'notice neutral';}}});
document.addEventListener('change',async event=>{const el=event.target;try{
 if(el.id==='active-date'){if(!el.value)return;activeDate=el.value;selectedDate=el.value;await save(d=>{d.settings.activeDate=activeDate;});}
 if(el.id.startsWith('filter-')){questionFilters[el.id.slice(7)]=el.value;$('#question-results').innerHTML=questionResults();}
 if(el.id==='import-file'&&el.files[0]){const file=el.files[0];if(file.size>1000000)throw new Error('הגיבוי גדול מדי. יש לבחור קובץ יצוא של האתר.');const imported=JSON.parse(await file.text());openDialog('import-confirm','import-confirm','בדיקת גיבוי לפני יבוא',`<p>היבוא יחליף את ההתקדמות המקומית בעותק שבחרת. לפני ההחלפה יישמר גיבוי של המצב הנוכחי.</p><div class="notice neutral">קובץ: ${esc(file.name)}<br>יחידות מעודכנות: ${Object.keys(imported.sessionUpdates||{}).length}<br>שאלות מתועדות: ${Object.keys(imported.problemProgress||{}).length}</div><div class="dialog-actions"><button class="button primary" id="confirm-import">יבוא הגיבוי הזה</button><button class="button" data-action="close">ביטול</button></div>`);$('#confirm-import').onclick=async()=>{try{await saveQueue.catch(()=>{});const data=await StudyStorage.importState(imported,state.revision);state=data;applyPrivateAssessment();StudyCards.reset();activeDate=state.settings.activeDate||activeDate;selectedDate=activeDate;closeDialog();render();$('#save-status').textContent='✓ הגיבוי יובא ונשמר';notify('הגיבוי יובא בהצלחה');}catch(e){notify(e.message);}};}
 }catch(err){notify(err.message);}});
document.addEventListener('submit',async event=>{
 const form=event.target;if(!['session-form','problem-form','availability-form','journal-form','custom-task-form'].includes(form.id))return;event.preventDefault();const fields=Object.fromEntries(new FormData(form)),button=$('button[type=submit]',form);button.disabled=true;
 try{
 if(form.id==='session-form'){const id=form.dataset.id;await save(d=>{d.sessionUpdates[id]={...(d.sessionUpdates[id]||{}),status:fields.status,date:fields.date,start:fields.start,note:fields.note,actualMinutes:fields.actualMinutes===''?null:Number(fields.actualMinutes),updatedAt:new Date().toISOString(),...(sessionOf(id).kind==='mock'?{mock:{uninterrupted:!!fields.mockUninterrupted,noHelp:!!fields.mockNoHelp,newQuestions:!!fields.mockNewQuestions,scores:[1,2,3].map(n=>fields['score'+n]===''?null:Number(fields['score'+n]))}}:{})};if(fields.note&&fields.note!==state.sessionUpdates[id]?.note)d.journal.push({date:activeDate,title:sessionOf(id).title,text:fields.note});},'המשימה עודכנה');closeDialog();}
 if(form.id==='problem-form'){const independent=['independent','timed'].includes(fields.status);if(independent&&(!fields.independentConfirmed||fields.evidence.trim().length<8)){ $('#problem-error').textContent='לסימון פתרון עצמאי צריך לאשר שלא נעזרת בהכוונה ולתעד בקצרה כיצד בדקת את הפתרון.';return;}if(fields.status==='timed'&&!Number(fields.minutes)){$('#problem-error').textContent='לפתרון בזמן יש לרשום את מספר הדקות שנמדד.';return;}await save(d=>{d.problemProgress[form.dataset.id]={...fields,minutes:fields.minutes?Number(fields.minutes):null,independentConfirmed:!!fields.independentConfirmed,updatedAt:new Date().toISOString()};},'מצב הפתרון נשמר');closeDialog();}
 if(form.id==='availability-form'){await save(d=>{d.dayOverrides[form.dataset.date]={...(d.dayOverrides[form.dataset.date]||{}),capacityMinutes:Number(fields.capacityMinutes),notes:fields.notes,confirmedOptional:!!fields.confirmedOptional};},'הזמינות עודכנה; המשימות נשארו במקומן');closeDialog();}
 if(form.id==='custom-task-form'){await save(d=>{d.settings.customSessions||=[];d.settings.customSessions.push({id:'repair-'+Date.now(),date:fields.date,start:fields.start,minutes:Number(fields.minutes),title:fields.title,kind:'practice',topicId:fields.topicId,problemIds:fields.problemId?[fields.problemId]:[],priority:'core',objective:fields.objective,steps:['להגדיר את הפער לפי הניסיון הקודם.','להיעזר במקור ממוקד רק במקום שבו נתקעת.','לנסות שוב בלי פתרון פתוח ולתעד את התוצאה.'],doneWhen:'נשמר ניסיון עצמאי ותועד מה השתפר ומה נותר פתוח.',dependsOn:[],conditional:false,stage:'independent'});},'משימת התיקון שובצה');closeDialog();selectedDate=fields.date;location.hash='schedule';render();}
 if(form.id==='journal-form'){await save(d=>d.journal.push({date:activeDate,title:fields.title,text:fields.text}),'הרשומה נשמרה');closeDialog();}
 }catch(err){}finally{button.disabled=false;}
});
$('#theme-button').addEventListener('click',()=>save(d=>{d.settings.theme=d.settings.theme==='light'?'dark':'light';}).catch(()=>{}));
$('#settings-button').addEventListener('click',()=>state&&showSettings());
$('#detail-dialog').addEventListener('click',event=>{if(event.target===$('#detail-dialog')){const r=event.target.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeDialog();}});
window.addEventListener('hashchange',()=>{closeDialog({restore:false});if(state){render();main.focus();window.scrollTo(0,0);}});
function applyPrivateAssessment(){
 const baseline=state.settings?.baselineAssessment;
 if(baseline){Object.assign(curriculum.meta,baseline.meta||{});for(const topic of curriculum.topics){const saved=baseline.topics?.find(t=>t.id===topic.id);if(saved)Object.assign(topic,saved);}}
}
async function exportProgress(){
 await saveQueue.catch(()=>{});
 const exported=await StudyStorage.exportState();exported.settings||={};
 if(curriculum.meta.diagnosticCompleted){
   exported.settings.baselineAssessment={meta:Object.fromEntries(['assessment','diagnosticCompleted','diagnosticSeconds','diagnosticLimit'].map(k=>[k,curriculum.meta[k]])),topics:curriculum.topics.map(t=>Object.fromEntries(['id','status','readiness','strengths','gaps'].map(k=>[k,t[k]])))};
 }
 downloadFile('study-progress.json',JSON.stringify(exported,null,2),'application/json;charset=utf-8');
 notify('הגיבוי הורד. אפשר לייבא אותו באתר המקוון או בדפדפן אחר.');
}
async function init(){try{({curriculum,schedule,state,flashcards}=await StudyStorage.bootstrap());flashcards||={cards:[]};SourceLibrary.init(curriculum);applyPrivateAssessment();state.sessionUpdates||={};state.problemProgress||={};state.dayOverrides||={};state.journal||=[];state.settings||={};activeDate=state.settings.activeDate||(window.STUDY_CONFIG?.preview?'2026-09-22':safeDate(dateNow()));selectedDate=activeDate;render();$('#save-status').textContent=StudyStorage.mode==='static'?'✓ ההתקדמות נשמרת בדפדפן הזה':'✓ הנתונים נטענו מהמחשב';$('.local-tag').innerHTML=StudyStorage.mode==='static'?'<i></i> ההתקדמות נשמרת בדפדפן':'<i></i> מרחב אישי · מקומי';if(window.StudyMeetings?.enabled())StudyMeetings.onReady();}catch(err){main.innerHTML=`<div class="panel"><h1>לא הצלחנו לפתוח את התוכנית</h1><p class="subtitle">${esc(err.message)}. ${StudyStorage.mode==='static'?'נסה לרענן ובדוק שהקבצים פורסמו ב־GitHub Pages.':'ודא שהשרת המקומי פועל דרך Start-Study.cmd.'}</p><a class="button" href="./" style="margin-top:20px">ניסיון נוסף</a></div>`;}}
init();
